/// <reference path="../edge-runtime.d.ts" />
import "jsr:@supabase/functions-js/edge-runtime.d.ts";
import { createClient, type SupabaseClient } from "https://esm.sh/@supabase/supabase-js@2";
import {
  getUserFromBearer,
  requireActiveOrg,
  requireTikTokShopPlatformConfigured,
  readPlatformTikTokShopOAuth,
  tiktokShopCorsHeaders,
  tiktokShopJson,
  type TikTokShopPlatformOAuth,
} from "../_shared/tiktokShopAuth.ts";
import {
  listTikTokShopConversationMessages,
  listTikTokShopConversations,
  TikTokShopApiError,
} from "../_shared/tiktokShopApi.ts";
import { getTikTokShopAccessToken } from "../_shared/tiktokShopOrgResolver.ts";

const RATE_LIMIT = 60;
const RATE_WINDOW_MS = 30 * 60 * 1000;

type ShopAccountRow = {
  id: string;
  seller_open_id: string;
  shop_id: string;
  shop_cipher: string;
  shop_name: string | null;
  is_default: boolean;
  is_active: boolean;
};

function mapCsErrorCode(ttsCode: number | undefined): string {
  switch (ttsCode) {
    case 45101004:
      return "TTS_DAILY_QUOTA";
    case 45101003:
      return "TTS_NOT_FOUND";
    case 45101001:
    case 36009003:
      return "TTS_INTERNAL";
    default:
      return "TIKTOK_SHOP_API_ERROR";
  }
}

function normalizeLocale(raw: string): string {
  return raw.toLowerCase().startsWith("id") ? "id-ID" : "en";
}

async function resolveAccount(
  admin: SupabaseClient,
  organizationId: string,
  accountIdHint: string,
): Promise<ShopAccountRow | Response> {
  let accountQuery = admin
    .from("organization_tiktok_shop_accounts")
    .select("id, seller_open_id, shop_id, shop_cipher, shop_name, is_default, is_active")
    .eq("organization_id", organizationId)
    .eq("is_active", true);

  if (accountIdHint) {
    accountQuery = accountQuery.eq("id", accountIdHint);
  } else {
    accountQuery = accountQuery
      .order("is_default", { ascending: false })
      .order("sort_order", { ascending: true });
  }

  const { data: accounts, error: accErr } = await accountQuery.limit(1);
  if (accErr) return tiktokShopJson({ error: accErr.message }, 500);

  const account = (accounts ?? [])[0] as ShopAccountRow | undefined;
  if (!account?.shop_cipher || !account.seller_open_id) {
    return tiktokShopJson(
      {
        error: "No active TikTok Shop account. Connect TikTok Shop in Settings.",
        code: "NOT_CONNECTED",
      },
      400,
    );
  }
  return account;
}

async function gateRateLimit(
  admin: SupabaseClient,
  organizationId: string,
): Promise<Response | null> {
  const nowMs = Date.now();
  const windowStartIso = new Date(nowMs - RATE_WINDOW_MS).toISOString();
  const { data: callRows } = await admin
    .from("tiktok_shop_cs_api_calls")
    .select("created_at")
    .eq("organization_id", organizationId)
    .gte("created_at", windowStartIso)
    .order("created_at", { ascending: true });

  const stamps = (callRows ?? []).map((r) => String((r as { created_at: string }).created_at));
  if (stamps.length >= RATE_LIMIT) {
    const oldest = stamps[0] ? new Date(stamps[0]).getTime() : nowMs;
    const retryAfterSeconds = Math.max(
      1,
      Math.ceil((oldest + RATE_WINDOW_MS - nowMs) / 1000),
    );
    return tiktokShopJson(
      {
        error:
          "TikTok Shop chat API rate limit reached (60 requests per 30 minutes). Try again later.",
        code: "RATE_LIMIT",
        retryAfterSeconds,
      },
      429,
    );
  }
  return null;
}

async function resolveAccessToken(
  admin: SupabaseClient,
  organizationId: string,
  sellerOpenId: string,
): Promise<string | Response> {
  let accessToken: string | null;
  try {
    accessToken = await getTikTokShopAccessToken(admin, organizationId, sellerOpenId);
  } catch (e) {
    const msg = e instanceof Error ? e.message : String(e);
    return tiktokShopJson(
      { error: msg || "Failed to load TikTok Shop access token", code: "TOKEN_ERROR" },
      400,
    );
  }
  if (!accessToken) {
    return tiktokShopJson(
      {
        error: "TikTok Shop access token unavailable. Reconnect in Settings.",
        code: "TOKEN_ERROR",
      },
      400,
    );
  }
  return accessToken;
}

async function recordCall(
  admin: SupabaseClient,
  organizationId: string,
  account: ShopAccountRow,
  action: string,
  requestId?: string,
) {
  await admin.from("tiktok_shop_cs_api_calls").insert({
    organization_id: organizationId,
    account_id: account.id,
    shop_id: account.shop_id,
    action,
    request_id: requestId ?? null,
    created_at: new Date().toISOString(),
  });
  const pruneBefore = new Date(Date.now() - 24 * 60 * 60 * 1000).toISOString();
  await admin.from("tiktok_shop_cs_api_calls").delete().lt("created_at", pruneBefore);
}

function apiErrorResponse(
  e: unknown,
  account: ShopAccountRow,
  logLabel: string,
): Response {
  const apiErr = e instanceof TikTokShopApiError ? e : null;
  const msg = e instanceof Error ? e.message : String(e);
  console.error(`tiktok-shop-customer-service ${logLabel}:`, msg);
  return tiktokShopJson(
    {
      error: msg,
      code: mapCsErrorCode(apiErr?.code),
      tts_code: apiErr?.code ?? null,
      request_id: apiErr?.requestId ?? null,
      shop_id: account.shop_id,
      shop_account_id: account.id,
    },
    400,
  );
}

Deno.serve(async (req: Request) => {
  if (req.method === "OPTIONS") {
    return new Response("ok", { status: 200, headers: tiktokShopCorsHeaders });
  }
  if (req.method !== "POST") {
    return tiktokShopJson({ error: "Method not allowed" }, 405);
  }

  const supabaseUrl = Deno.env.get("SUPABASE_URL") ?? "";
  const serviceRoleKey = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY") ?? "";
  if (!supabaseUrl || !serviceRoleKey) {
    return tiktokShopJson({ error: "Server misconfigured" }, 500);
  }

  const admin = createClient(supabaseUrl, serviceRoleKey);
  const userRes = await getUserFromBearer(admin, req.headers.get("Authorization"));
  if ("error" in userRes) return userRes.error;

  let body: Record<string, unknown>;
  try {
    body = (await req.json()) as Record<string, unknown>;
  } catch {
    return tiktokShopJson({ error: "Invalid JSON body" }, 400);
  }

  const action = String(body.action ?? "").trim();
  const organizationId = String(body.organization_id ?? "").trim();
  if (!organizationId) return tiktokShopJson({ error: "Missing organization_id" }, 400);

  const orgForbidden = await requireActiveOrg(admin, userRes.userId, organizationId);
  if (orgForbidden) return orgForbidden;

  const platformForbidden = requireTikTokShopPlatformConfigured();
  if (platformForbidden) return platformForbidden;

  if (action !== "listConversations" && action !== "listMessages") {
    return tiktokShopJson({ error: `Unknown action: ${action}` }, 400);
  }

  const accountOrErr = await resolveAccount(
    admin,
    organizationId,
    String(body.account_id ?? "").trim(),
  );
  if (accountOrErr instanceof Response) return accountOrErr;
  const account = accountOrErr;

  const limited = await gateRateLimit(admin, organizationId);
  if (limited) return limited;

  const oauth = readPlatformTikTokShopOAuth();
  if (!oauth) {
    return tiktokShopJson({ error: "TikTok Shop is not configured on server." }, 503);
  }

  const tokenOrErr = await resolveAccessToken(admin, organizationId, account.seller_open_id);
  if (typeof tokenOrErr !== "string") return tokenOrErr;
  const accessToken = tokenOrErr;

  const locale = normalizeLocale(String(body.locale ?? "en").trim());
  const pageToken = String(body.page_token ?? "").trim();

  if (action === "listMessages") {
    return handleListMessages({
      admin,
      organizationId,
      account,
      oauth,
      accessToken,
      locale,
      pageToken,
      conversationId: String(body.conversation_id ?? "").trim(),
    });
  }

  return handleListConversations({
    admin,
    organizationId,
    account,
    oauth,
    accessToken,
    locale,
    pageToken,
  });
});

async function handleListConversations(params: {
  admin: SupabaseClient;
  organizationId: string;
  account: ShopAccountRow;
  oauth: TikTokShopPlatformOAuth;
  accessToken: string;
  locale: string;
  pageToken: string;
}): Promise<Response> {
  const { admin, organizationId, account, oauth, accessToken, locale, pageToken } = params;
  try {
    const result = await listTikTokShopConversations(oauth, accessToken, {
      shop_cipher: account.shop_cipher,
      page_size: 20,
      page_token: pageToken || undefined,
      locale,
    });
    await recordCall(admin, organizationId, account, "listConversations", result.requestId);
    return tiktokShopJson(
      {
        next_page_token: result.data.next_page_token ?? "",
        conversations: result.data.conversations,
        account: {
          id: account.id,
          shop_id: account.shop_id,
          shop_name: account.shop_name,
        },
        request_id: result.requestId ?? null,
      },
      200,
    );
  } catch (e) {
    const apiErr = e instanceof TikTokShopApiError ? e : null;
    await recordCall(admin, organizationId, account, "listConversations", apiErr?.requestId);
    return apiErrorResponse(e, account, "listConversations");
  }
}

async function handleListMessages(params: {
  admin: SupabaseClient;
  organizationId: string;
  account: ShopAccountRow;
  oauth: TikTokShopPlatformOAuth;
  accessToken: string;
  locale: string;
  pageToken: string;
  conversationId: string;
}): Promise<Response> {
  const {
    admin,
    organizationId,
    account,
    oauth,
    accessToken,
    locale,
    pageToken,
    conversationId,
  } = params;

  if (!conversationId) {
    return tiktokShopJson({ error: "Missing conversation_id", code: "VALIDATION" }, 400);
  }

  try {
    const result = await listTikTokShopConversationMessages(oauth, accessToken, {
      conversation_id: conversationId,
      shop_cipher: account.shop_cipher,
      page_size: 10,
      page_token: pageToken || undefined,
      locale,
      sort_order: "DESC",
      sort_field: "create_time",
      need_plaintext: true,
      need_data: false,
      time_zone: "Asia/Jakarta",
    });
    await recordCall(admin, organizationId, account, "listMessages", result.requestId);
    return tiktokShopJson(
      {
        next_page_token: result.data.next_page_token ?? "",
        unsupported_msg_tips: result.data.unsupported_msg_tips ?? "",
        messages: result.data.messages,
        account: {
          id: account.id,
          shop_id: account.shop_id,
          shop_name: account.shop_name,
        },
        request_id: result.requestId ?? null,
      },
      200,
    );
  } catch (e) {
    const apiErr = e instanceof TikTokShopApiError ? e : null;
    await recordCall(admin, organizationId, account, "listMessages", apiErr?.requestId);
    return apiErrorResponse(e, account, "listMessages");
  }
}

import type { SupabaseClient } from "https://esm.sh/@supabase/supabase-js@2";

export const tiktokShopCorsHeaders: Record<string, string> = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type",
  "Access-Control-Allow-Methods": "GET, POST, OPTIONS",
  "Access-Control-Max-Age": "86400",
};

export const TIKTOK_SHOP_API_BASE_DEFAULT = "https://open-api.tiktokglobalshop.com";
export const TIKTOK_SHOP_AUTH_AUTHORIZE_BASE_DEFAULT = "https://services.tiktokshop.com";
/** Token exchange/refresh host (separate from open-api seller endpoints). */
export const TIKTOK_SHOP_AUTH_TOKEN_BASE_DEFAULT = "https://auth.tiktok-shops.com";

export function tiktokShopJson(body: object, status: number): Response {
  return new Response(JSON.stringify(body), {
    status,
    headers: { ...tiktokShopCorsHeaders, "Content-Type": "application/json" },
  });
}

export type TikTokShopPlatformOAuth = {
  appKey: string;
  appSecret: string;
  serviceId: string;
};

export function readPlatformTikTokShopOAuth(): TikTokShopPlatformOAuth | null {
  const appKey = Deno.env.get("TIKTOK_SHOP_APP_KEY")?.trim() ??
    Deno.env.get("TIKTOK_SHOP_CLIENT_KEY")?.trim() ?? "";
  const appSecret = Deno.env.get("TIKTOK_SHOP_APP_SECRET")?.trim() ??
    Deno.env.get("TIKTOK_SHOP_CLIENT_SECRET")?.trim() ?? "";
  const serviceId = Deno.env.get("TIKTOK_SHOP_SERVICE_ID")?.trim() ?? "";
  if (!appKey || !appSecret || !serviceId) return null;
  return { appKey, appSecret, serviceId };
}

export function isTikTokShopPlatformConfigured(): boolean {
  return readPlatformTikTokShopOAuth() !== null;
}

export function requireTikTokShopPlatformConfigured(): Response | null {
  if (!isTikTokShopPlatformConfigured()) {
    return tiktokShopJson(
      {
        error:
          "TikTok Shop is not configured. Set TIKTOK_SHOP_APP_KEY, TIKTOK_SHOP_APP_SECRET, and TIKTOK_SHOP_SERVICE_ID in Supabase Edge Function secrets.",
      },
      503,
    );
  }
  return null;
}

export function tiktokShopApiBase(): string {
  const explicit = Deno.env.get("TIKTOK_SHOP_API_BASE")?.trim();
  if (explicit) return explicit.replace(/\/+$/, "");
  return TIKTOK_SHOP_API_BASE_DEFAULT;
}

export function tiktokShopAuthAuthorizeBase(): string {
  const explicit = Deno.env.get("TIKTOK_SHOP_AUTH_AUTHORIZE_BASE")?.trim();
  if (explicit) return explicit.replace(/\/+$/, "");
  return TIKTOK_SHOP_AUTH_AUTHORIZE_BASE_DEFAULT;
}

export function tiktokShopAuthTokenBase(): string {
  const explicit = Deno.env.get("TIKTOK_SHOP_AUTH_TOKEN_BASE")?.trim();
  if (explicit) return explicit.replace(/\/+$/, "");
  return TIKTOK_SHOP_AUTH_TOKEN_BASE_DEFAULT;
}

export function tiktokShopOAuthRedirectUri(): string {
  const explicit = Deno.env.get("TIKTOK_SHOP_OAUTH_REDIRECT_URI")?.trim();
  if (explicit) return explicit;
  const supabaseUrl = (Deno.env.get("SUPABASE_URL") ?? "").replace(/\/+$/, "");
  return `${supabaseUrl}/functions/v1/tiktok-shop-oauth-callback`;
}

export function appPublicOrigin(): string {
  const raw =
    Deno.env.get("APP_PUBLIC_URL")?.trim() ??
    Deno.env.get("SYNCKERJA_APP_URL")?.trim() ??
    "";
  return raw.replace(/\/+$/, "");
}

export const TIKTOK_SHOP_OAUTH_RETURN_PATHS = new Set([
  "/operations/sales/tiktok-shop/settings",
  "/digital-marketing/tiktok-shop/settings",
]);

export async function getUserFromBearer(
  admin: SupabaseClient,
  authHeader: string | null,
): Promise<{ userId: string } | { error: Response }> {
  const token = authHeader?.startsWith("Bearer ") ? authHeader.slice("Bearer ".length).trim() : "";
  if (!token) return { error: tiktokShopJson({ error: "Unauthorized" }, 401) };
  const { data: userRes, error: userErr } = await admin.auth.getUser(token);
  if (userErr || !userRes?.user?.id) {
    return { error: tiktokShopJson({ error: "Invalid token" }, 401) };
  }
  return { userId: userRes.user.id };
}

export async function isOmnichannelShopAdmin(
  admin: SupabaseClient,
  userId: string,
  organizationId: string,
): Promise<boolean> {
  const { data: owner } = await admin
    .from("user_roles")
    .select("id")
    .eq("user_id", userId)
    .eq("organization_id", organizationId)
    .eq("role", "owner")
    .maybeSingle();
  if (owner) return true;

  const { data: staffRows } = await admin
    .from("organization_omnichannel_staff")
    .select("employee_id, employees!inner(user_id)")
    .eq("organization_id", organizationId)
    .eq("role", "admin");

  for (const row of staffRows ?? []) {
    const emp = row as { employees?: { user_id?: string } | { user_id?: string }[] };
    const employees = emp.employees;
    const userIds: string[] = [];
    if (Array.isArray(employees)) {
      for (const e of employees) {
        if (e?.user_id) userIds.push(String(e.user_id));
      }
    } else if (employees && typeof employees === "object" && "user_id" in employees) {
      const uid = (employees as { user_id?: string }).user_id;
      if (uid) userIds.push(String(uid));
    }
    if (userIds.includes(userId)) return true;
  }
  return false;
}

export async function requireOrgAdmin(
  admin: SupabaseClient,
  userId: string,
  organizationId: string,
): Promise<Response | null> {
  const ok = await isOmnichannelShopAdmin(admin, userId, organizationId);
  if (!ok) return tiktokShopJson({ error: "Forbidden" }, 403);
  return null;
}

export async function requireActiveOrg(
  admin: SupabaseClient,
  userId: string,
  organizationId: string,
): Promise<Response | null> {
  const { data: profile } = await admin
    .from("profiles")
    .select("active_organization_id")
    .eq("user_id", userId)
    .maybeSingle();
  const activeOrg = profile?.active_organization_id != null ? String(profile.active_organization_id) : "";
  if (!activeOrg || activeOrg !== organizationId) {
    return tiktokShopJson({ error: "Forbidden" }, 403);
  }
  return null;
}

import {
  tiktokShopApiBase,
  tiktokShopAuthAuthorizeBase,
  tiktokShopAuthTokenBase,
  type TikTokShopPlatformOAuth,
} from "./tiktokShopAuth.ts";
import { computeTikTokShopSign } from "./tiktokShopSign.ts";

type TikTokShopApiEnvelope<T> = {
  code?: number;
  message?: string;
  data?: T;
  request_id?: string;
};

export type TikTokShopTokenResult = {
  access_token: string;
  refresh_token: string;
  seller_open_id: string;
  seller_name?: string;
  seller_base_region?: string;
  access_token_expire_in?: number;
  refresh_token_expire_in?: number;
};

export type TikTokShopAuthorizedShop = {
  shop_id: string;
  shop_cipher: string;
  shop_name: string;
  region?: string;
  seller_type?: string;
};

export class TikTokShopApiError extends Error {
  code?: number;
  requestId?: string;

  constructor(prefix: string, message?: string, code?: number, requestId?: string) {
    const detail = message?.trim() || (code != null ? `code ${code}` : "unknown");
    super(`${prefix}: ${detail}`);
    this.name = "TikTokShopApiError";
    this.code = code;
    this.requestId = requestId;
  }
}

function throwApiError(
  prefix: string,
  message?: string,
  code?: number,
  requestId?: string,
): never {
  throw new TikTokShopApiError(prefix, message, code, requestId);
}

function parseEnvelope<T>(
  json: TikTokShopApiEnvelope<T>,
  prefix: string,
  options?: { allowEmptyData?: boolean },
): T {
  const code = json.code;
  const message = json.message?.trim() ?? "";
  const requestId = json.request_id;
  if (code !== 0 && code !== undefined) {
    throwApiError(prefix, message, code, requestId);
  }
  if (json.data === undefined || json.data === null) {
    if (options?.allowEmptyData) {
      return {} as T;
    }
    throwApiError(prefix, message || "empty data", code, requestId);
  }
  return json.data;
}

export function buildTikTokShopSellerAuthUrl(
  oauth: TikTokShopPlatformOAuth,
  state: string,
): string {
  const params = new URLSearchParams({
    service_id: oauth.serviceId,
    state,
  });
  return `${tiktokShopAuthAuthorizeBase()}/open/authorize?${params.toString()}`;
}

export async function exchangeTikTokShopAuthCode(
  oauth: TikTokShopPlatformOAuth,
  authCode: string,
): Promise<TikTokShopTokenResult> {
  const code = authCode.trim();
  if (!code) throw new Error("token_exchange_failed: missing auth_code");

  const params = new URLSearchParams({
    app_key: oauth.appKey,
    app_secret: oauth.appSecret,
    auth_code: code,
    grant_type: "authorized_code",
  });
  const url = `${tiktokShopAuthTokenBase()}/api/v2/token/get?${params.toString()}`;
  const res = await fetch(url, { method: "GET" });
  const json = await res.json().catch(() => ({})) as TikTokShopApiEnvelope<Record<string, unknown>>;
  if (!res.ok) {
    throwApiError("token_exchange_failed", json.message, json.code ?? res.status);
  }
  const data = parseEnvelope(json, "token_exchange_failed");
  return normalizeTokenResult(data);
}

export async function refreshTikTokShopAccessToken(
  oauth: TikTokShopPlatformOAuth,
  refreshToken: string,
): Promise<TikTokShopTokenResult | null> {
  const token = refreshToken.trim();
  if (!token) return null;

  const params = new URLSearchParams({
    app_key: oauth.appKey,
    app_secret: oauth.appSecret,
    refresh_token: token,
    grant_type: "refresh_token",
  });
  const url = `${tiktokShopAuthTokenBase()}/api/v2/token/refresh?${params.toString()}`;
  const res = await fetch(url, { method: "GET" });
  const json = await res.json().catch(() => ({})) as TikTokShopApiEnvelope<Record<string, unknown>>;
  if (!res.ok || (json.code !== 0 && json.code !== undefined)) {
    console.warn("refreshTikTokShopAccessToken:", json.message ?? res.status);
    return null;
  }
  if (!json.data) return null;
  return normalizeTokenResult(json.data);
}

function normalizeTokenResult(data: Record<string, unknown>): TikTokShopTokenResult {
  const accessToken = String(data.access_token ?? "").trim();
  const refreshToken = String(data.refresh_token ?? "").trim();
  const openId = String(data.open_id ?? data.seller_open_id ?? "").trim();
  const sellerName = data.seller_name != null ? String(data.seller_name).trim() : undefined;
  const sellerBaseRegion = data.seller_base_region != null
    ? String(data.seller_base_region).trim()
    : undefined;

  let sellerOpenId = openId;
  if (!sellerOpenId) {
    const fallbackName = sellerName ?? "seller";
    const region = sellerBaseRegion ?? "unknown";
    sellerOpenId = `fallback_${fallbackName}_${region}`.replace(/\s+/g, "_").slice(0, 120);
  }

  if (!accessToken) throw new Error("token_exchange_failed: missing access_token");

  const accessExpire = parseExpireSeconds(data.access_token_expire_in ?? data.access_token_expires_in);
  const refreshExpire = parseExpireSeconds(data.refresh_token_expire_in ?? data.refresh_token_expires_in);

  return {
    access_token: accessToken,
    refresh_token: refreshToken || accessToken,
    seller_open_id: sellerOpenId,
    seller_name: sellerName,
    seller_base_region: sellerBaseRegion,
    access_token_expire_in: accessExpire,
    refresh_token_expire_in: refreshExpire,
  };
}

function parseExpireSeconds(raw: unknown): number | undefined {
  if (raw == null) return undefined;
  const n = Number(raw);
  if (!Number.isFinite(n) || n <= 0) return undefined;
  return Math.floor(n);
}

/**
 * TikTok Shop token responses use absolute Unix expiry timestamps (seconds), not TTL duration.
 * Values below 1e9 are treated as TTL seconds from now (legacy fallback).
 */
export function tokenExpiresAtIsoFromTikTokField(
  raw: unknown,
  nowMs = Date.now(),
): string | null {
  if (raw == null) return null;
  const n = Number(raw);
  if (!Number.isFinite(n) || n <= 0) return null;
  if (n >= 1_000_000_000) {
    const ms = n >= 1_000_000_000_000 ? n : n * 1000;
    return new Date(ms).toISOString();
  }
  return new Date(nowMs + n * 1000).toISOString();
}

export type TikTokShopOrderRow = {
  order_id: string;
  status: string;
  create_time: number | null;
  gmv: number;
  currency: string;
  units_sold: number;
  buyer_message?: string | null;
};

export type TikTokShopOrderSearchResult = {
  orders: TikTokShopOrderRow[];
  total_count: number | null;
  next_page_token: string | null;
};

const TIKTOK_SHOP_DEFAULT_CURRENCY = "IDR";

function parseTikTokShopMoneyValue(
  raw: unknown,
  fallbackCurrency = TIKTOK_SHOP_DEFAULT_CURRENCY,
): { amount: number; currency: string } {
  if (raw == null || raw === "") {
    return { amount: 0, currency: fallbackCurrency };
  }

  if (typeof raw === "number" || typeof raw === "string") {
    const n = Number(raw);
    return { amount: Number.isFinite(n) ? n : 0, currency: fallbackCurrency };
  }

  if (Array.isArray(raw) && raw.length > 0) {
    return parseTikTokShopMoneyValue(raw[0], fallbackCurrency);
  }

  if (typeof raw === "object") {
    const p = raw as Record<string, unknown>;
    const currency = String(
      p.currency ??
        p.currency_code ??
        p.currency_name ??
        p.currencyName ??
        fallbackCurrency,
    ).trim() || fallbackCurrency;

    const amountCandidates = [
      p.sale_price_decimal,
      p.sale_price,
      p.amount,
      p.tax_exclusive_price,
      p.original_price,
      p.price,
      p.value,
    ];

    for (const candidate of amountCandidates) {
      if (candidate == null || candidate === "") continue;
      if (typeof candidate === "object") {
        const nested = parseTikTokShopMoneyValue(candidate, currency);
        if (nested.amount !== 0 || nested.currency !== fallbackCurrency) return nested;
        continue;
      }
      const n = Number(candidate);
      if (Number.isFinite(n)) return { amount: n, currency };
    }

    return { amount: 0, currency };
  }

  return { amount: 0, currency: fallbackCurrency };
}

function parseOrderAmount(payment: unknown): { gmv: number; currency: string } {
  if (!payment || typeof payment !== "object") {
    return { gmv: 0, currency: TIKTOK_SHOP_DEFAULT_CURRENCY };
  }
  const p = payment as Record<string, unknown>;
  const parsed = parseTikTokShopMoneyValue(
    p.total_amount ??
      p.original_total_product_price ??
      p.sub_total ??
      p.product_price ??
      payment,
    String(p.currency ?? p.currency_code ?? TIKTOK_SHOP_DEFAULT_CURRENCY).trim() ||
      TIKTOK_SHOP_DEFAULT_CURRENCY,
  );
  return { gmv: parsed.amount, currency: parsed.currency };
}

function parseOrderUnits(lineItems: unknown): number {
  if (!Array.isArray(lineItems)) return 0;
  let units = 0;
  for (const item of lineItems) {
    if (!item || typeof item !== "object") continue;
    const row = item as Record<string, unknown>;
    const qty = Number(row.quantity ?? row.sku_quantity ?? row.product_quantity ?? 1);
    units += Number.isFinite(qty) && qty > 0 ? qty : 1;
  }
  return units;
}

function normalizeTikTokShopOrder(raw: Record<string, unknown>): TikTokShopOrderRow | null {
  const orderId = String(raw.id ?? raw.order_id ?? "").trim();
  if (!orderId) return null;
  const status = String(raw.status ?? raw.order_status ?? "UNKNOWN").trim() || "UNKNOWN";
  const createRaw = raw.create_time ?? raw.created_time;
  const createTime = createRaw != null && Number.isFinite(Number(createRaw))
    ? Math.floor(Number(createRaw))
    : null;
  const payment = raw.payment ?? raw.payment_info;
  const { gmv, currency } = parseOrderAmount(payment);
  const units = parseOrderUnits(raw.line_items ?? raw.line_item_list ?? raw.items);
  return {
    order_id: orderId,
    status,
    create_time: createTime,
    gmv,
    currency,
    units_sold: units,
    buyer_message: raw.buyer_message != null ? String(raw.buyer_message) : null,
  };
}

function aggregateOrderSummary(orders: TikTokShopOrderRow[]): {
  gmv: number;
  units_sold: number;
  currency: string;
} {
  let gmv = 0;
  let units = 0;
  let currency = TIKTOK_SHOP_DEFAULT_CURRENCY;
  for (const order of orders) {
    gmv += order.gmv;
    units += order.units_sold;
    if (order.currency) currency = order.currency;
  }
  return { gmv, units_sold: units, currency };
}

export async function searchTikTokShopOrders(
  oauth: TikTokShopPlatformOAuth,
  accessToken: string,
  shopCipher: string,
  options: {
    createTimeGe: number;
    createTimeLt: number;
    pageSize?: number;
    pageToken?: string;
    orderStatus?: string;
  },
): Promise<TikTokShopOrderSearchResult> {
  const cipher = shopCipher.trim();
  if (!cipher) throw new Error("tiktok_shop_api: missing shop_cipher");

  const pageSize = Math.min(Math.max(options.pageSize ?? 50, 1), 100);
  const query: Record<string, string> = {
    shop_cipher: cipher,
    page_size: String(pageSize),
  };
  if (options.pageToken?.trim()) {
    query.page_token = options.pageToken.trim();
  }

  const body: Record<string, unknown> = {
    create_time_ge: options.createTimeGe,
    create_time_lt: options.createTimeLt,
  };
  if (options.orderStatus?.trim()) {
    body.order_status = options.orderStatus.trim();
  }

  const data = await signedTikTokShopRequest<Record<string, unknown>>(
    oauth,
    accessToken,
    "POST",
    "/order/202309/orders/search",
    {
      query,
      body,
      allowEmptyData: true,
    },
  );

  const rawOrders = (data.orders ?? data.order_list ?? []) as Array<Record<string, unknown>>;
  const orders = rawOrders
    .map((row) => normalizeTikTokShopOrder(row))
    .filter((row): row is TikTokShopOrderRow => row != null);

  const totalRaw = data.total_count ?? data.total ?? data.order_count;
  const totalCount = totalRaw != null && Number.isFinite(Number(totalRaw))
    ? Math.floor(Number(totalRaw))
    : null;

  const nextPage = data.next_page_token ?? data.page_token;
  const nextPageToken = nextPage != null && String(nextPage).trim()
    ? String(nextPage).trim()
    : null;

  return { orders, total_count: totalCount, next_page_token: nextPageToken };
}

export function summarizeTikTokShopOrders(orders: TikTokShopOrderRow[]): {
  gmv: number;
  units_sold: number;
  currency: string;
} {
  return aggregateOrderSummary(orders);
}

export type TikTokShopOrderLineItem = {
  sku_id: string;
  seller_sku: string;
  product_name: string;
  quantity: number;
  sale_price: number;
  currency: string;
};

export type TikTokShopOrderDetail = TikTokShopOrderRow & {
  update_time: number | null;
  shipping_type: string | null;
  tracking_number: string | null;
  recipient_name: string | null;
  recipient_phone: string | null;
  recipient_address: string | null;
  payment_subtotal: number | null;
  payment_shipping: number | null;
  payment_tax: number | null;
  payment_discount: number | null;
  line_items: TikTokShopOrderLineItem[];
};

function parseAddressText(raw: unknown): string | null {
  if (raw == null) return null;
  if (typeof raw === "string") return raw.trim() || null;
  if (typeof raw !== "object") return null;
  const a = raw as Record<string, unknown>;
  const parts = [
    a.full_address,
    a.address_line1 ?? a.address_line_1,
    a.address_line2 ?? a.address_line_2,
    a.address_detail,
    a.district,
    a.city,
    a.state,
    a.region,
    a.postal_code ?? a.zipcode,
    a.country,
  ]
    .map((p) => (p != null ? String(p).trim() : ""))
    .filter(Boolean);
  return parts.length > 0 ? parts.join(", ") : null;
}

function parseOrderLineItems(raw: unknown): TikTokShopOrderLineItem[] {
  if (!Array.isArray(raw)) return [];
  const items: TikTokShopOrderLineItem[] = [];
  for (const item of raw) {
    if (!item || typeof item !== "object") continue;
    const row = item as Record<string, unknown>;
    const sku = row.sku_id ?? row.skuId;
    const sellerSku = row.seller_sku ?? row.sellerSku ?? sku;
    const name = String(row.product_name ?? row.product_title ?? row.title ?? sellerSku ?? "Item").trim();
    const qty = Number(row.quantity ?? row.sku_quantity ?? 1);
    const priceSource = row.sale_price ?? row.original_price ?? row.price ?? row.price_info;
    const { amount: price, currency: parsedCurrency } = parseTikTokShopMoneyValue(priceSource);
    const currency = String(
      row.currency ?? row.currency_code ?? row.currency_name ?? parsedCurrency,
    ).trim() || parsedCurrency;
    items.push({
      sku_id: sku != null ? String(sku) : "",
      seller_sku: sellerSku != null ? String(sellerSku) : "",
      product_name: name,
      quantity: Number.isFinite(qty) && qty > 0 ? qty : 1,
      sale_price: price,
      currency,
    });
  }
  return items;
}

function normalizeTikTokShopOrderDetail(raw: Record<string, unknown>): TikTokShopOrderDetail | null {
  const base = normalizeTikTokShopOrder(raw);
  if (!base) return null;
  const updateRaw = raw.update_time ?? raw.updated_time;
  const updateTime = updateRaw != null && Number.isFinite(Number(updateRaw))
    ? Math.floor(Number(updateRaw))
    : null;
  const payment = raw.payment ?? raw.payment_info;
  let paymentSubtotal: number | null = null;
  let paymentShipping: number | null = null;
  let paymentTax: number | null = null;
  let paymentDiscount: number | null = null;
  if (payment && typeof payment === "object") {
    const p = payment as Record<string, unknown>;
    const sub = Number(p.sub_total ?? p.original_total_product_price);
    const ship = Number(p.shipping_fee ?? p.shipping_amount);
    const tax = Number(p.tax ?? p.total_tax);
    const disc = Number(p.seller_discount ?? p.platform_discount ?? p.discount);
    if (Number.isFinite(sub)) paymentSubtotal = sub;
    if (Number.isFinite(ship)) paymentShipping = ship;
    if (Number.isFinite(tax)) paymentTax = tax;
    if (Number.isFinite(disc)) paymentDiscount = disc;
  }
  const recipient = raw.recipient_address ?? raw.shipping_address ?? raw.delivery_address;
  const recipientObj = recipient && typeof recipient === "object"
    ? recipient as Record<string, unknown>
    : null;
  const packages = raw.packages ?? raw.package_list;
  let tracking: string | null = null;
  if (Array.isArray(packages) && packages[0] && typeof packages[0] === "object") {
    const pkg = packages[0] as Record<string, unknown>;
    tracking = pkg.tracking_number != null ? String(pkg.tracking_number) : null;
  }
  return {
    ...base,
    update_time: updateTime,
    shipping_type: raw.shipping_type != null ? String(raw.shipping_type) : null,
    tracking_number: tracking ?? (raw.tracking_number != null ? String(raw.tracking_number) : null),
    recipient_name: recipientObj?.name != null ? String(recipientObj.name) : null,
    recipient_phone: recipientObj?.phone_number != null
      ? String(recipientObj.phone_number)
      : recipientObj?.phone != null
        ? String(recipientObj.phone)
        : null,
    recipient_address: parseAddressText(recipient),
    payment_subtotal: paymentSubtotal,
    payment_shipping: paymentShipping,
    payment_tax: paymentTax,
    payment_discount: paymentDiscount,
    line_items: parseOrderLineItems(raw.line_items ?? raw.line_item_list ?? raw.items),
  };
}

export async function getTikTokShopOrderDetails(
  oauth: TikTokShopPlatformOAuth,
  accessToken: string,
  shopCipher: string,
  orderIds: string[],
): Promise<{ orders: TikTokShopOrderDetail[] }> {
  const cipher = shopCipher.trim();
  if (!cipher) throw new Error("tiktok_shop_api: missing shop_cipher");
  const ids = orderIds.map((id) => id.trim()).filter(Boolean).slice(0, 50);
  if (ids.length === 0) throw new Error("tiktok_shop_api: missing order ids");

  const data = await signedTikTokShopRequest<Record<string, unknown>>(
    oauth,
    accessToken,
    "GET",
    "/order/202309/orders",
    {
      query: {
        shop_cipher: cipher,
        ids: ids.join(","),
      },
      allowEmptyData: true,
    },
  );

  const rawOrders = (data.orders ?? data.order_list ?? []) as Array<Record<string, unknown>>;
  const orders = rawOrders
    .map((row) => normalizeTikTokShopOrderDetail(row))
    .filter((row): row is TikTokShopOrderDetail => row != null);
  return { orders };
}

export const TIKTOK_SHOP_MAX_SUMMARY_PAGES = 20;

export type TikTokShopOrderPeriodSummary = {
  gmv: number;
  order_count: number;
  units_sold: number;
  currency: string;
  pages_fetched: number;
  truncated: boolean;
};

export async function aggregateOrderSearchPages(
  oauth: TikTokShopPlatformOAuth,
  accessToken: string,
  shopCipher: string,
  options: {
    createTimeGe: number;
    createTimeLt: number;
    orderStatus?: string;
    maxPages?: number;
  },
): Promise<TikTokShopOrderPeriodSummary> {
  const maxPages = Math.min(Math.max(options.maxPages ?? TIKTOK_SHOP_MAX_SUMMARY_PAGES, 1), 50);
  const allOrders: TikTokShopOrderRow[] = [];
  let pageToken: string | undefined;
  let pagesFetched = 0;
  let totalCount: number | null = null;
  let truncated = false;

  while (pagesFetched < maxPages) {
    const result = await searchTikTokShopOrders(oauth, accessToken, shopCipher, {
      createTimeGe: options.createTimeGe,
      createTimeLt: options.createTimeLt,
      pageSize: 50,
      pageToken,
      orderStatus: options.orderStatus,
    });
    allOrders.push(...result.orders);
    if (result.total_count != null) totalCount = result.total_count;
    pagesFetched++;
    if (!result.next_page_token) break;
    pageToken = result.next_page_token;
    if (pagesFetched >= maxPages) {
      truncated = true;
      break;
    }
  }

  const summary = summarizeTikTokShopOrders(allOrders);
  return {
    gmv: summary.gmv,
    order_count: totalCount ?? allOrders.length,
    units_sold: summary.units_sold,
    currency: summary.currency,
    pages_fetched: pagesFetched,
    truncated,
  };
}

export type TikTokShopProductSku = {
  sku_id: string;
  seller_sku: string;
  price: number;
  currency: string;
  stock: number | null;
};

export type TikTokShopProductRow = {
  product_id: string;
  title: string;
  status: string;
  create_time: number | null;
  update_time: number | null;
  skus: TikTokShopProductSku[];
};

export type TikTokShopProductSearchResult = {
  products: TikTokShopProductRow[];
  total_count: number | null;
  next_page_token: string | null;
};

function parseSkuStockFromRow(row: Record<string, unknown>): number | null {
  const direct = row.stock ?? row.available_stock ?? row.quantity;
  if (direct != null && Number.isFinite(Number(direct))) {
    return Math.floor(Number(direct));
  }

  const stockInfos = row.stock_infos ?? row.stockInfos;
  if (Array.isArray(stockInfos)) {
    let total = 0;
    let found = false;
    for (const item of stockInfos) {
      if (!item || typeof item !== "object") continue;
      const info = item as Record<string, unknown>;
      const qty = info.available_stock ?? info.stock ?? info.quantity;
      if (qty != null && Number.isFinite(Number(qty))) {
        total += Math.floor(Number(qty));
        found = true;
      }
    }
    if (found) return total;
  }

  const inventory = row.inventory;
  if (Array.isArray(inventory)) {
    let total = 0;
    let found = false;
    for (const item of inventory) {
      if (!item || typeof item !== "object") continue;
      const inv = item as Record<string, unknown>;
      const qty = inv.quantity ?? inv.available_stock ?? inv.stock;
      if (qty != null && Number.isFinite(Number(qty))) {
        total += Math.floor(Number(qty));
        found = true;
      }
    }
    if (found) return total;
  }

  if (inventory != null && typeof inventory === "object" && !Array.isArray(inventory)) {
    const inv = inventory as Record<string, unknown>;
    const qty = inv.quantity ?? inv.available_stock ?? inv.stock;
    if (qty != null && Number.isFinite(Number(qty))) {
      return Math.floor(Number(qty));
    }
  }

  return null;
}

function parseProductSkus(raw: unknown): TikTokShopProductSku[] {
  if (!Array.isArray(raw)) return [];
  const skus: TikTokShopProductSku[] = [];
  for (const item of raw) {
    if (!item || typeof item !== "object") continue;
    const row = item as Record<string, unknown>;
    const skuId = String(row.id ?? row.sku_id ?? "").trim();
    const sellerSku = String(row.seller_sku ?? row.sellerSku ?? skuId).trim();
    const priceSource = row.price ?? row.price_info ?? row.original_price ?? row.sale_price;
    const { amount: price, currency: parsedCurrency } = parseTikTokShopMoneyValue(priceSource);
    const currency = String(
      row.currency ?? row.currency_code ?? row.currency_name ?? parsedCurrency,
    ).trim() || parsedCurrency;
    const stock = parseSkuStockFromRow(row);
    skus.push({ sku_id: skuId, seller_sku: sellerSku, price, currency, stock });
  }
  return skus;
}

function normalizeTikTokShopProduct(raw: Record<string, unknown>): TikTokShopProductRow | null {
  const productId = String(raw.id ?? raw.product_id ?? "").trim();
  if (!productId) return null;
  const title = String(raw.title ?? raw.product_name ?? raw.name ?? productId).trim();
  const status = String(raw.status ?? raw.product_status ?? "UNKNOWN").trim() || "UNKNOWN";
  const createRaw = raw.create_time ?? raw.created_time;
  const updateRaw = raw.update_time ?? raw.updated_time;
  const createTime = createRaw != null && Number.isFinite(Number(createRaw))
    ? Math.floor(Number(createRaw))
    : null;
  const updateTime = updateRaw != null && Number.isFinite(Number(updateRaw))
    ? Math.floor(Number(updateRaw))
    : null;
  return {
    product_id: productId,
    title,
    status,
    create_time: createTime,
    update_time: updateTime,
    skus: parseProductSkus(raw.skus ?? raw.sku_list ?? raw.sku),
  };
}

export async function searchTikTokShopProducts(
