  id?: string;
  type?: string;
  content?: string;
  create_time?: number;
  is_visible?: boolean;
  sender?: {
    im_user_id?: string;
    avatar?: string;
    role?: string;
    nickname?: string;
  };
  index?: string;
  data?: string;
  plaintext?: string;
};

