  next_page_token?: string;
  conversations: TikTokShopConversation[];
};

export type TikTokShopConversationMessagesList = {
  next_page_token?: string;
  unsupported_msg_tips?: string;
  messages: TikTokShopConversationMessage[];
};

export async function listTikTokShopConversations(
  oauth: TikTokShopPlatformOAuth,
  accessToken: string,
  params: {
    shop_cipher: string;
    page_size?: number;
    page_token?: string;
    locale?: string;
  },
): Promise<TikTokShopSignedResult<TikTokShopConversationsList>> {
  const cipher = String(params.shop_cipher ?? "").trim();
  if (!cipher) throw new Error("tiktok_shop_api: missing shop_cipher");

  let pageSize = Number(params.page_size ?? 20);
  if (!Number.isFinite(pageSize) || pageSize < 1) pageSize = 20;
  if (pageSize > 20) pageSize = 20;

  const locale = String(params.locale ?? "en").trim() || "en";
  const query: Record<string, string> = {
    shop_cipher: cipher,
    page_size: String(pageSize),
    locale,
    need_session_id: "false",
    need_session_info: "false",
  };
  const pageToken = String(params.page_token ?? "").trim();
  if (pageToken) query.page_token = pageToken;

  const result = await signedTikTokShopRequestFull<{
    next_page_token?: string;
    conversations?: TikTokShopConversation[];
  }>(oauth, accessToken, "GET", "/customer_service/202309/conversations", { query });

  const conversations = (result.data.conversations ?? [])
    .map((c) => ({
      ...c,
      id: String(c.id ?? "").trim(),
    }))
    .filter((c) => Boolean(c.id));

  return {
    data: {
      next_page_token: String(result.data.next_page_token ?? ""),
      conversations,
    },
    requestId: result.requestId,
  };
}

export async function listTikTokShopConversationMessages(
  oauth: TikTokShopPlatformOAuth,
  accessToken: string,
  params: {
    conversation_id: string;
    shop_cipher: string;
    page_size?: number;
    page_token?: string;
    locale?: string;
    sort_order?: string;
    sort_field?: string;
    need_plaintext?: boolean;
    need_data?: boolean;
    time_zone?: string;
  },
): Promise<TikTokShopSignedResult<TikTokShopConversationMessagesList>> {
  const conversationId = String(params.conversation_id ?? "").trim();
  if (!conversationId) throw new Error("tiktok_shop_api: missing conversation_id");

  const cipher = String(params.shop_cipher ?? "").trim();
  if (!cipher) throw new Error("tiktok_shop_api: missing shop_cipher");

  let pageSize = Number(params.page_size ?? 10);
  if (!Number.isFinite(pageSize) || pageSize < 1) pageSize = 10;
  if (pageSize > 10) pageSize = 10;

  const locale = String(params.locale ?? "en").trim() || "en";
  const sortOrder = String(params.sort_order ?? "DESC").trim().toUpperCase() === "ASC"
    ? "ASC"
    : "DESC";
  const sortField = String(params.sort_field ?? "create_time").trim() || "create_time";
  const needPlaintext = params.need_plaintext !== false;
  const needData = params.need_data === true;
  const timeZone = String(params.time_zone ?? "Asia/Jakarta").trim() || "Asia/Jakarta";

  const query: Record<string, string> = {
    shop_cipher: cipher,
    page_size: String(pageSize),
    locale,
    sort_order: sortOrder,
    sort_field: sortField,
    need_plaintext: needPlaintext ? "true" : "false",
    need_data: needData ? "true" : "false",
    time_zone: timeZone,
  };
  const pageToken = String(params.page_token ?? "").trim();
  if (pageToken) query.page_token = pageToken;

  const path =
    `/customer_service/202309/conversations/${encodeURIComponent(conversationId)}/messages`;

  const result = await signedTikTokShopRequestFull<{
    next_page_token?: string;
    unsupported_msg_tips?: string;
    messages?: TikTokShopConversationMessage[];
  }>(oauth, accessToken, "GET", path, { query });

  const messages = (result.data.messages ?? [])
    .map((m) => ({
      ...m,
      id: String(m.id ?? "").trim(),
    }))
    .filter((m) => Boolean(m.id));

  return {
    data: {
      next_page_token: String(result.data.next_page_token ?? ""),
      unsupported_msg_tips: result.data.unsupported_msg_tips != null
        ? String(result.data.unsupported_msg_tips)
        : undefined,
      messages,
    },
    requestId: result.requestId,
  };
}

export async function getTikTokShopAuthorizedShops(
  oauth: TikTokShopPlatformOAuth,
  accessToken: string,
): Promise<TikTokShopAuthorizedShop[]> {
  const data = await signedTikTokShopRequest<{ shops?: Array<Record<string, unknown>> }>(
    oauth,
    accessToken,
    "GET",
    "/authorization/202309/shops",
  );

  const shops = data.shops ?? [];
  return shops.map((shop) => {
    const shopId = String(shop.id ?? shop.shop_id ?? "").trim();
    const cipher = String(shop.cipher ?? shop.shop_cipher ?? "").trim();
    const name = String(shop.name ?? shop.shop_name ?? shopId).trim();
    return {
      shop_id: shopId,
      shop_cipher: cipher,
      shop_name: name || shopId,
      region: shop.region != null ? String(shop.region).trim() : undefined,
      seller_type: shop.seller_type != null ? String(shop.seller_type).trim() : undefined,
    };
  }).filter((s) => s.shop_id && s.shop_cipher);
}

/**
 * TikTok Shop Partner API request signing.
 * Mirror: src/tiktok-shop/lib/tiktokShopSigning.ts (keep algorithms in sync).
 */

export type TikTokShopSignInput = {
  path: string;
  queryParams: Record<string, string>;
  body?: string;
  appSecret: string;
};

function sortObjectKeys(params: Record<string, string>): Record<string, string> {
  const sorted: Record<string, string> = {};
  for (const key of Object.keys(params).sort()) {
    sorted[key] = params[key];
  }
  return sorted;
}

export function buildTikTokShopSignString(
  path: string,
  queryParams: Record<string, string>,
  body: string,
  appSecret: string,
): string {
  const filtered: Record<string, string> = {};
  for (const [key, value] of Object.entries(queryParams)) {
    if (key === "sign" || key === "access_token") continue;
    filtered[key] = value;
  }
  const sorted = sortObjectKeys(filtered);
  let paramString = "";
  for (const [key, value] of Object.entries(sorted)) {
    paramString += `${key}${value}`;
  }
  return `${appSecret}${path}${paramString}${body}${appSecret}`;
}

async function hmacSha256Hex(message: string, secret: string): Promise<string> {
  const key = await crypto.subtle.importKey(
    "raw",
    new TextEncoder().encode(secret),
    { name: "HMAC", hash: "SHA-256" },
    false,
    ["sign"],
  );
  const sig = await crypto.subtle.sign("HMAC", key, new TextEncoder().encode(message));
  const bytes = new Uint8Array(sig);
  return Array.from(bytes)
    .map((b) => b.toString(16).padStart(2, "0"))
    .join("");
}

export async function computeTikTokShopSign(input: TikTokShopSignInput): Promise<string> {
  const signString = buildTikTokShopSignString(
    input.path,
    input.queryParams,
    input.body ?? "",
    input.appSecret,
  );
  return await hmacSha256Hex(signString, input.appSecret);
}

import type { SupabaseClient } from "https://esm.sh/@supabase/supabase-js@2";
import {
  decryptTikTokShopToken,
  encryptTikTokShopToken,
} from "./tiktokShopConfigCrypto.ts";
import { readPlatformTikTokShopOAuth } from "./tiktokShopAuth.ts";
import {
  getTikTokShopAuthorizedShops,
  refreshTikTokShopAccessToken,
  tokenExpiresAtIsoFromTikTokField,
  type TikTokShopAuthorizedShop,
} from "./tiktokShopApi.ts";
import { isTikTokShopExpiredCredentialsError } from "./tiktokShopAuthErrors.ts";

export type TikTokShopAccountRow = {
  id: string;
  organization_id: string;
  seller_open_id: string;
  shop_id: string;
  shop_cipher: string;
  shop_name: string | null;
  region: string | null;
  seller_type: string | null;
  label: string;
  is_default: boolean;
  is_active: boolean;
  sort_order: number;
};

type TokenRow = {
  access_token_enc: string;
  refresh_token_enc: string;
  access_token_expires_at: string | null;
  seller_name: string | null;
  seller_base_region: string | null;
};

export async function getTikTokShopAccessToken(
  admin: SupabaseClient,
  organizationId: string,
  sellerOpenId: string,
  options?: { forceRefresh?: boolean },
): Promise<string | null> {
  const { data: row } = await admin
    .from("organization_tiktok_shop_connection_tokens")
    .select(
      "access_token_enc, refresh_token_enc, access_token_expires_at, seller_name, seller_base_region",
    )
    .eq("organization_id", organizationId)
    .eq("seller_open_id", sellerOpenId)
    .maybeSingle();
  if (!row?.access_token_enc || !row?.refresh_token_enc) return null;

  const tokenRow = row as TokenRow;
  const expiresAtMs = tokenRow.access_token_expires_at
    ? new Date(String(tokenRow.access_token_expires_at)).getTime()
    : null;
  const needsRefresh = options?.forceRefresh === true || (
    expiresAtMs != null &&
    Number.isFinite(expiresAtMs) &&
    expiresAtMs < Date.now() + 60_000
  );

  if (!needsRefresh) {
    try {
      return await decryptTikTokShopToken(String(tokenRow.access_token_enc));
    } catch (e) {
      console.error("getTikTokShopAccessToken decrypt:", e);
      return null;
    }
  }

  let refreshToken: string;
  try {
    refreshToken = await decryptTikTokShopToken(String(tokenRow.refresh_token_enc));
  } catch (e) {
    console.error("getTikTokShopAccessToken refresh decrypt:", e);
    return null;
  }

  const oauth = readPlatformTikTokShopOAuth();
  const refreshed = oauth ? await refreshTikTokShopAccessToken(oauth, refreshToken) : null;

  if (!refreshed?.access_token) {
    return null;
  }

  try {
    const now = new Date().toISOString();
    const accessEnc = await encryptTikTokShopToken(refreshed.access_token);
    const refreshEnc = refreshed.refresh_token
      ? await encryptTikTokShopToken(refreshed.refresh_token)
      : String(tokenRow.refresh_token_enc);
    const accessExpires = tokenExpiresAtIsoFromTikTokField(refreshed.access_token_expire_in)
      ?? tokenRow.access_token_expires_at;
    const refreshExpires = tokenExpiresAtIsoFromTikTokField(refreshed.refresh_token_expire_in);

    await admin.from("organization_tiktok_shop_connection_tokens").update({
      access_token_enc: accessEnc,
      refresh_token_enc: refreshEnc,
      access_token_expires_at: accessExpires,
      refresh_token_expires_at: refreshExpires,
      seller_name: refreshed.seller_name ?? tokenRow.seller_name,
      seller_base_region: refreshed.seller_base_region ?? tokenRow.seller_base_region,
      updated_at: now,
    }).eq("organization_id", organizationId).eq("seller_open_id", sellerOpenId);

    return refreshed.access_token;
  } catch (e) {
    console.error("getTikTokShopAccessToken re-encrypt:", e);
    return refreshed.access_token;
  }
}

export async function listTikTokShopSellerOpenIds(
  admin: SupabaseClient,
  organizationId: string,
): Promise<string[]> {
  const { data } = await admin
    .from("organization_tiktok_shop_connection_tokens")
    .select("seller_open_id")
    .eq("organization_id", organizationId);
  return (data ?? []).map((r) => String((r as { seller_open_id: string }).seller_open_id));
}

export async function resolveDefaultShopAccount(
  admin: SupabaseClient,
  organizationId: string,
): Promise<TikTokShopAccountRow | null> {
  const { data: defaultRow } = await admin
    .from("organization_tiktok_shop_accounts")
    .select(
      "id, organization_id, seller_open_id, shop_id, shop_cipher, shop_name, region, seller_type, label, is_default, is_active, sort_order",
    )
    .eq("organization_id", organizationId)
    .eq("is_active", true)
    .eq("is_default", true)
    .maybeSingle();
  if (defaultRow) return defaultRow as TikTokShopAccountRow;

  const { data: first } = await admin
    .from("organization_tiktok_shop_accounts")
    .select(
      "id, organization_id, seller_open_id, shop_id, shop_cipher, shop_name, region, seller_type, label, is_default, is_active, sort_order",
    )
    .eq("organization_id", organizationId)
    .eq("is_active", true)
    .order("sort_order", { ascending: true })
    .limit(1)
    .maybeSingle();
  return (first as TikTokShopAccountRow | null) ?? null;
}

export async function syncTikTokShopAccountsForSeller(
  admin: SupabaseClient,
  organizationId: string,
  sellerOpenId: string,
  shops: TikTokShopAuthorizedShop[],
): Promise<{ upserted: number; isExistingSeller: boolean }> {
  const sellerId = sellerOpenId.trim();
  const { data: existingShops } = await admin
    .from("organization_tiktok_shop_accounts")
    .select("id, shop_id, is_default")
    .eq("organization_id", organizationId)
    .eq("seller_open_id", sellerId);

  const existingSellerShopIds = new Set(
    (existingShops ?? []).map((r) => String((r as { shop_id: string }).shop_id)),
  );
  const isExistingSeller = existingSellerShopIds.size > 0;

  const { data: allActiveShops } = await admin
    .from("organization_tiktok_shop_accounts")
    .select("is_default")
    .eq("organization_id", organizationId)
    .eq("is_active", true);

  const orgHasDefault = (allActiveShops ?? []).some(
    (r) => Boolean((r as { is_default?: boolean }).is_default),
  );

  const now = new Date().toISOString();
  let upserted = 0;
  let firstNewInBatch = !orgHasDefault;

  for (const shop of shops) {
    const shopId = shop.shop_id.trim();
    if (!shopId) continue;
    const isExistingShop = existingSellerShopIds.has(shopId);
    const existingDefault = (existingShops ?? []).find(
      (r) => String((r as { shop_id: string }).shop_id) === shopId,
    ) as { is_default?: boolean } | undefined;

    const { error } = await admin.from("organization_tiktok_shop_accounts").upsert(
      {
        organization_id: organizationId,
        seller_open_id: sellerId,
        shop_id: shopId,
        shop_cipher: shop.shop_cipher,
        shop_name: shop.shop_name,
        region: shop.region ?? null,
        seller_type: shop.seller_type ?? null,
        label: shop.shop_name || shopId,
        is_default: isExistingShop
          ? Boolean(existingDefault?.is_default)
          : firstNewInBatch,
        is_active: true,
        updated_at: now,
      },
      { onConflict: "organization_id,shop_id" },
    );
    if (!error) {
      upserted++;
      if (!isExistingShop && firstNewInBatch) firstNewInBatch = false;
    } else {
      console.error("syncTikTokShopAccountsForSeller upsert:", error.message);
    }
  }

  return { upserted, isExistingSeller };
}

export async function resolveOrgTikTokShopForOrders(
  admin: SupabaseClient,
  organizationId: string,
  shopAccountIdOrShopId: string | null,
): Promise<{ accessToken: string; account: TikTokShopAccountRow } | null> {
  const param = shopAccountIdOrShopId?.trim() ?? "";
  let account: TikTokShopAccountRow | null = null;

  if (param) {
    const { data: byId } = await admin
      .from("organization_tiktok_shop_accounts")
      .select(
        "id, organization_id, seller_open_id, shop_id, shop_cipher, shop_name, region, seller_type, label, is_default, is_active, sort_order",
      )
      .eq("organization_id", organizationId)
      .eq("id", param)
      .eq("is_active", true)
      .maybeSingle();
    if (byId) {
      account = byId as TikTokShopAccountRow;
    } else {
      const { data: byShopId } = await admin
        .from("organization_tiktok_shop_accounts")
        .select(
          "id, organization_id, seller_open_id, shop_id, shop_cipher, shop_name, region, seller_type, label, is_default, is_active, sort_order",
        )
        .eq("organization_id", organizationId)
        .eq("shop_id", param)
        .eq("is_active", true)
        .maybeSingle();
      account = (byShopId as TikTokShopAccountRow | null) ?? null;
    }
  }

  if (!account) {
    account = await resolveDefaultShopAccount(admin, organizationId);
  }
  if (!account?.shop_cipher || !account.seller_open_id) return null;

  const accessToken = await getTikTokShopAccessToken(
    admin,
    organizationId,
    account.seller_open_id,
  );
  if (!accessToken) return null;

  return { accessToken, account };
}

/** Retry once with a forced token refresh when TikTok returns expired-credentials errors. */
export async function withTikTokShopAccessTokenRetry<T>(
  admin: SupabaseClient,
  organizationId: string,
  sellerOpenId: string,
  accessToken: string,
  fn: (token: string) => Promise<T>,
): Promise<T> {
  try {
    return await fn(accessToken);
  } catch (e) {
    const msg = e instanceof Error ? e.message : String(e);
    if (!isTikTokShopExpiredCredentialsError(msg)) throw e;
    const freshToken = await getTikTokShopAccessToken(
      admin,
      organizationId,
      sellerOpenId,
      { forceRefresh: true },
    );
    if (!freshToken) throw e;
    return await fn(freshToken);
  }
}

export async function fetchAndSyncAuthorizedShops(
  admin: SupabaseClient,
  organizationId: string,
  sellerOpenId: string,
): Promise<TikTokShopAuthorizedShop[]> {
  const oauth = readPlatformTikTokShopOAuth();
  if (!oauth) throw new Error("Platform not configured");

  const accessToken = await getTikTokShopAccessToken(admin, organizationId, sellerOpenId);
  if (!accessToken) throw new Error("Seller not connected");

  const shops = await getTikTokShopAuthorizedShops(oauth, accessToken);
  await syncTikTokShopAccountsForSeller(admin, organizationId, sellerOpenId, shops);
  return shops;
}

/** Detect TikTok Shop API responses when the seller access token is no longer valid. */
export function isTikTokShopExpiredCredentialsError(message: string): boolean {
  const lower = message.toLowerCase();
  return (
    lower.includes("expired credentials") ||
    (lower.includes("access_token") && lower.includes("expired")) ||
    (lower.includes("x-tts-access-token") && lower.includes("expired")) ||
    lower.includes("invalid access token")
  );
}

export function isTikTokShopScopeOrAuthError(message: string): boolean {
  const lower = message.toLowerCase();
  return (
    isTikTokShopExpiredCredentialsError(message) ||
    lower.includes("access denied") ||
    lower.includes("scope") ||
    lower.includes("permission") ||
    lower.includes("unauthorized")
  );
}

/**
 * AES-256-GCM for TikTok Shop OAuth tokens.
 * Key: TIKTOK_SHOP_CONFIG_ENCRYPTION_KEY (fallback TIKTOK_ADS_CONFIG_ENCRYPTION_KEY).
 */

const ALGO = "AES-GCM";
const IV_LEN = 12;
const TAG_LEN = 128;

function decodeKey(raw: string): Uint8Array {
  const trimmed = raw.trim();
  if (!trimmed) throw new Error("Encryption key is not set");
  if (/^[0-9a-fA-F]{64}$/.test(trimmed)) {
    const bytes = new Uint8Array(32);
    for (let i = 0; i < 32; i++) {
      bytes[i] = parseInt(trimmed.slice(i * 2, i * 2 + 2), 16);
    }
    return bytes;
  }
  const bin = atob(trimmed);
  const bytes = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
  if (bytes.length !== 32) {
    throw new Error("Encryption key must be 32 bytes (base64 or 64-char hex)");
  }
  return bytes;
}

function getKeyBytes(): Uint8Array {
  const raw = Deno.env.get("TIKTOK_SHOP_CONFIG_ENCRYPTION_KEY")?.trim() ??
    Deno.env.get("TIKTOK_ADS_CONFIG_ENCRYPTION_KEY") ?? "";
  return decodeKey(raw);
}

function toBase64(bytes: Uint8Array): string {
  let s = "";
  for (let i = 0; i < bytes.length; i++) s += String.fromCharCode(bytes[i]);
  return btoa(s);
}

function fromBase64(b64: string): Uint8Array {
  const bin = atob(b64);
  const out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
  return out;
}

async function encrypt(plaintext: string): Promise<string> {
  const keyBytes = getKeyBytes();
  const iv = crypto.getRandomValues(new Uint8Array(IV_LEN));
  const key = await crypto.subtle.importKey("raw", keyBytes, { name: ALGO }, false, ["encrypt"]);
  const enc = await crypto.subtle.encrypt(
    { name: ALGO, iv, tagLength: TAG_LEN },
    key,
    new TextEncoder().encode(plaintext),
  );
  const combined = new Uint8Array(iv.length + enc.byteLength);
  combined.set(iv, 0);
  combined.set(new Uint8Array(enc), iv.length);
  return toBase64(combined);
}

async function decrypt(ciphertextB64: string): Promise<string> {
  const keyBytes = getKeyBytes();
  const combined = fromBase64(ciphertextB64.trim());
  if (combined.length < IV_LEN + 16) throw new Error("Invalid encrypted token payload");
  const iv = combined.slice(0, IV_LEN);
  const data = combined.slice(IV_LEN);
  const key = await crypto.subtle.importKey("raw", keyBytes, { name: ALGO }, false, ["decrypt"]);
  const dec = await crypto.subtle.decrypt({ name: ALGO, iv, tagLength: TAG_LEN }, key, data);
  return new TextDecoder().decode(dec);
}

export async function encryptTikTokShopToken(plaintext: string): Promise<string> {
  return encrypt(plaintext);
}

export async function decryptTikTokShopToken(ciphertextB64: string): Promise<string> {
  return decrypt(ciphertextB64);
}
